custom_qss:
/* ============================================================
   MAGENTA — hot magenta + soft rose on dark plum.
   Rounded, borderless. Two-hue sweep (magenta -> rose) on every
   interactive fill. Fully round indicators. Soft top-edge sheen
   baked into the vertical gradients (QSS glow is ignored, so the
   light comes from the gradient itself). Uppercase letter-spaced
   dock + group labels.
   ============================================================ */

* {
    border: none;
    background-color: transparent !important;
    color: #f2e2f2;
}
QAbstractScrollArea, QFrame, QStackedWidget, QScrollArea, QTabWidget, QWidget {
    background: transparent !important; border: none;
}

/* window: plum lift at the floor */
QMainWindow {
    background: qlineargradient(x1:0, y1:0, x2:0.14, y2:1,
        stop:0 #251134, stop:0.4 #1a0a1e, stop:0.75 #150818, stop:1 #1e0d28) !important;
}
QDialog {
    background: qlineargradient(x1:0, y1:0, x2:0.3, y2:1,
        stop:0 #251134, stop:0.5 #1a0c24, stop:1 #120716) !important;
}

/* menubar */
QMenuBar { background: transparent !important; }
QMenuBar::item {
    padding: 5px 13px; border-radius: 8px; background: transparent !important;
    color: #8f6a96;
}
QMenuBar::item:selected {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #4a1c62, stop:1 #6d2a80) !important; color: #f2e2f2;
}
QMenuBar::item:disabled { color: #5c3f66; }

/* popup menus: big soft pills */
QMenu {
    background: qlineargradient(x1:0, y1:0, x2:0.3, y2:1,
        stop:0 #2c1440, stop:1 #1a0c24) !important;
    border-radius: 14px; padding: 7px;
}
QMenu::item {
    padding: 7px 26px 7px 14px; border-radius: 9px; background: transparent !important;
    color: #f2e2f2;
}
QMenu::item:selected {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #e84fc0, stop:0.55 #f0619a, stop:1 #f794b8) !important;
    color: #ffffff !important;
}
QMenu::item:disabled { color: #5c3f66; }
QMenu::separator { height: 1px; background: #3d1d4d; margin: 6px 10px; border-radius: 1px; }

/* toolbar */
QToolBar { background: transparent !important; spacing: 3px; padding: 4px; }
QToolBar::separator { background: #3d1d4d; width: 2px; margin: 6px 5px; border-radius: 1px; }
QToolBar QToolButton, QToolButton {
    background: transparent !important; padding: 6px 10px; border-radius: 9px;
    color: #8f6a96;
}
QToolBar QToolButton:hover, QToolButton:hover {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #43184f, stop:1 #2a1236) !important; color: #f58ade;
}
QToolBar QToolButton:checked, QToolBar QToolButton:pressed,
QToolButton:checked, QToolButton:pressed {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #e84fc0, stop:1 #f0619a) !important; color: #ffffff !important;
}

/* buttons: two-hue sheen */
QPushButton {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #451a56, stop:0.35 #33153f, stop:1 #241030) !important;
    border-radius: 13px; padding: 8px 22px; color: #f2e2f2; font-weight: 600;
}
QPushButton:hover {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #6d2a80, stop:0.12 #a03a8e, stop:0.55 #e84fc0, stop:1 #f0619a) !important;
    color: #ffffff !important;
}
QPushButton:pressed {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #241030, stop:0.5 #451a56, stop:0.9 #e84fc0, stop:1 #f0619a) !important;
    color: #ffffff !important;
}
QPushButton:checked {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #e84fc0, stop:0.5 #f0619a, stop:1 #f794b8) !important;
    color: #ffffff !important;
}
QPushButton:disabled { background: #1a0c24 !important; color: #5c3f66 !important; }

/* inputs */
QLineEdit, QSpinBox, QDoubleSpinBox, QTextEdit, QPlainTextEdit {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #2c1440, stop:1 #1e0d28) !important;
    border-radius: 11px; padding: 6px 12px; color: #f58ade;
    selection-background-color: #e84fc0; selection-color: #ffffff;
}
QLineEdit:focus, QSpinBox:focus, QDoubleSpinBox:focus, QTextEdit:focus, QPlainTextEdit:focus {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #3d1d4d, stop:1 #2c1440) !important; color: #ffffff !important;
}
QLineEdit:disabled, QSpinBox:disabled, QDoubleSpinBox:disabled,
QTextEdit:disabled, QPlainTextEdit:disabled { color: #5c3f66 !important; }
QSpinBox::up-button, QSpinBox::down-button,
QDoubleSpinBox::up-button, QDoubleSpinBox::down-button {
    background: transparent !important; border: none; width: 16px;
}

QComboBox {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #451a56, stop:1 #241030) !important;
    border-radius: 11px; padding: 6px 12px; color: #f2e2f2;
}
QComboBox:hover { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #552a68, stop:1 #33153f) !important; }
QComboBox:focus { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #e84fc0, stop:1 #f0619a) !important; }
QComboBox::drop-down { border: none; background: transparent !important; width: 18px; }
QComboBox QAbstractItemView {
    background: qlineargradient(x1:0, y1:0, x2:0.3, y2:1, stop:0 #2c1440, stop:1 #1a0c24) !important;
    border-radius: 13px; padding: 6px;
    selection-background-color: #e84fc0; selection-color: #ffffff;
}

/* checkboxes: FULLY round indicators (signature) */
QCheckBox, QRadioButton {
    color: #f2e2f2; background: transparent !important; padding: 3px;
}
QCheckBox::indicator, QRadioButton::indicator {
    width: 20px; height: 20px; border-radius: 10px;
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #3d1d4d, stop:1 #241030) !important;
}
QCheckBox::indicator:hover, QRadioButton::indicator:hover {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #552a68, stop:1 #3d1d4d) !important;
}
QCheckBox::indicator:checked, QRadioButton::indicator:checked {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:1, stop:0 #e84fc0, stop:1 #f0619a) !important;
}

/* tabs: thick pill, uppercase selected */
QTabBar::tab {
    background: transparent !important; color: #8f6a96;
    padding: 9px 18px; border-radius: 11px; margin: 0 1px;
}
QTabBar::tab:hover { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #331542, stop:1 #1a0c24) !important; color: #f58ade; }
QTabBar::tab:selected {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #e84fc0, stop:0.5 #f0619a, stop:1 #f794b8) !important;
    color: #ffffff !important; font-weight: 700; letter-spacing: 0.5px;
}
QTabWidget::pane { border: none; background: #1a0a1e; }

/* docks: metal gradient, uppercase letter-spaced title */
QDockWidget {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #251134, stop:0.6 #241030, stop:1 #1a0c24) !important;
    border: none;
}
QDockWidget::title {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #331542, stop:1 #1e0d28) !important;
    border-radius: 8px; margin: 3px; padding: 7px 11px;
    color: #c79ec7; font-size: 11px; font-weight: 700; letter-spacing: 1.5px;
}
QDockWidget::close-button, QDockWidget::float-button {
    background: transparent !important; border: none; border-radius: 6px; padding: 3px; icon-size: 13px;
}
QDockWidget::close-button:hover, QDockWidget::float-button:hover { background: #43184f !important; }

/* group boxes: uppercase rose label */
QGroupBox {
    background: transparent !important; border: none; border-radius: 12px; margin-top: 13px; padding-top: 11px;
}
QGroupBox::title {
    subcontrol-origin: margin; subcontrol-position: top left; padding: 0 9px;
    color: #f0619a; font-weight: 700; letter-spacing: 1.2px; background: #1a0a1e;
}

/* item views */
QAbstractItemView {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #1e0d28, stop:1 #150818) !important;
    border: none; border-radius: 12px; outline: none;
    alternate-background-color: #1a0c24;
    selection-background-color: #e84fc0; selection-color: #ffffff;
}
QAbstractItemView::item { padding: 6px 10px; border: none; color: #f2e2f2; border-radius: 8px; }
QAbstractItemView::item:hover { background: #2c1440 !important; }
QAbstractItemView::item:selected {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #e84fc0, stop:1 #f0619a) !important;
    color: #ffffff !important;
}
QTreeView::branch { background: transparent !important; }
QHeaderView::section {
    background: #1e0d28 !important; border: none; padding: 7px 11px;
    color: #8f6a96; font-size: 11px; font-weight: 700; letter-spacing: 1px;
}

/* scrollbars */
QScrollBar:vertical { background: transparent; width: 11px; margin: 0; border: none; }
QScrollBar::handle:vertical {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #552a68, stop:1 #3d1d4d) !important;
    border-radius: 6px; min-height: 32px;
}
QScrollBar::handle:vertical:hover { background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #e84fc0, stop:1 #f0619a) !important; }
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical { height: 0; border: none; background: none; }
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical { background: none; }
QScrollBar:horizontal { background: transparent; height: 11px; margin: 0; border: none; }
QScrollBar::handle:horizontal {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #552a68, stop:1 #3d1d4d) !important;
    border-radius: 6px; min-width: 32px;
}
QScrollBar::handle:horizontal:hover { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #e84fc0, stop:1 #f0619a) !important; }
QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal { width: 0; border: none; background: none; }
QScrollBar::add-page:horizontal, QScrollBar::sub-page:horizontal { background: none; }
QScrollBar::corner { background: none; }

/* sliders: two-hue fill, round handle */
QSlider::groove:horizontal { background: #150818; border: none; height: 6px; border-radius: 3px; }
QSlider::sub-page:horizontal { background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #e84fc0, stop:1 #f0619a) !important; border-radius: 3px; }
QSlider::add-page:horizontal { background: #150818; border-radius: 3px; }
QSlider::handle:horizontal {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #f58ade, stop:1 #e84fc0) !important;
    width: 16px; height: 16px; margin: -6px 0; border: none; border-radius: 9px;
}
QSlider::handle:horizontal:hover { background: #f794b8 !important; }
QSlider::groove:vertical { background: #150818; border: none; width: 6px; border-radius: 3px; }
QSlider::sub-page:vertical { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #e84fc0, stop:1 #f0619a) !important; border-radius: 3px; }
QSlider::handle:vertical {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #f58ade, stop:1 #e84fc0) !important;
    width: 16px; height: 16px; margin: 0 -6px; border: none; border-radius: 9px;
}

/* progress: two-hue sweep */
QProgressBar { background: #150818; border: none; border-radius: 8px; text-align: center; color: #c79ec7; font-size: 11px; min-height: 15px; }
QProgressBar::chunk { background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #e84fc0, stop:0.5 #f0619a, stop:1 #f794b8) !important; border-radius: 6px; }

/* statusbar + tooltip + splitter */
QStatusBar { background: transparent !important; color: #8f6a96; font-size: 11px; }
QStatusBar::item { border: none; }
QToolTip {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #2c1440, stop:1 #1a0c24) !important;
    border: 1px solid #3d1d4d; border-radius: 9px; padding: 7px 11px; color: #f2e2f2;
}
QSplitter::handle { background: #3d1d4d; border-radius: 2px; }
QSplitter::handle:hover { background: #e84fc0; }
QListView, QListWidget, QTreeWidget, QTableWidget { background: #150818 !important; border: none; border-radius: 12px; outline: none; }
